descriptor.templateCss:
.kv-root{font-family:'Mulish',Roboto,'Helvetica Neue',sans-serif;color:#24302A;height:100%;overflow-y:auto;overflow-x:hidden;box-sizing:border-box;padding:2px 2px 16px;display:flex;flex-direction:column;gap:16px;-webkit-font-smoothing:antialiased}
.kv-root *{box-sizing:border-box}
.kv-card{background:#fff;border:1px solid #DCE3DA;border-radius:12px;box-shadow:0 1px 3px rgba(36,48,42,.08)}
.kv-top{display:flex;flex-wrap:wrap;gap:16px}
.kv-ficha{flex:1 1 260px;max-width:100%;padding:18px 20px;display:flex;flex-direction:column;gap:6px;min-width:0}
.kv-eyebrow{font-size:11px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;color:#4F6B5C}
.kv-title{margin:0;font-family:'Playfair Display',Georgia,serif;font-size:26px;font-weight:700;line-height:1.15;color:#24302A;overflow-wrap:anywhere}
.kv-meta{font-size:13px;color:#5A534D;line-height:1.45}
.kv-meta b{color:#3D3833;font-weight:700}
.kv-kpis{flex:3 1 600px;display:grid;grid-template-columns:repeat(auto-fit,minmax(124px,1fr));gap:12px;min-width:0}
.kv-kpi{padding:14px;display:flex;flex-direction:column;gap:6px;min-width:0}
.kv-kpi-l{font-size:12px;color:#5A534D;font-weight:600}
.kv-kpi-v{font-size:24px;font-weight:800;color:#24302A;line-height:1.1;white-space:nowrap}
.kv-kpi-u{font-size:13px;font-weight:600;color:#5A534D;margin-left:4px}
.kv-kpi-d{font-size:12px;font-weight:600;color:#4F6B5C;min-height:15px}
.kv-nav{overflow:hidden}
.kv-tabsbar{display:flex;flex-wrap:wrap;align-items:flex-end;gap:4px 12px;padding:0 12px;border-bottom:1px solid #DCE3DA}
.kv-tabs{display:flex;gap:4px}
.kv-tab{min-height:48px;padding:0 20px;border:0;background:transparent;font-family:inherit;font-size:14px;font-weight:800;color:#5A534D;border-bottom:3px solid transparent;margin-bottom:-1px;cursor:pointer}
.kv-tab:hover{color:#24302A}
.kv-tab.sel{color:#24302A;border-bottom-color:#33513A;cursor:default}
.kv-tab:focus-visible,.kv-pill:focus-visible,.kv-btn:focus-visible,.kv-toggle:focus-visible{outline:2px solid #2F5D8A;outline-offset:2px}
.kv-live{margin-left:auto;padding-bottom:14px;font-size:13px;color:#4F6B5C;font-weight:700;display:inline-flex;align-items:center;gap:8px}
.kv-dot{width:8px;height:8px;border-radius:50%;background:#6E8A12;display:inline-block;box-shadow:0 0 0 3px rgba(110,138,18,.18)}
.kv-toolbar{padding:14px 16px;display:flex;flex-wrap:wrap;gap:14px 22px;align-items:flex-end;background:#FAFBF9}
.kv-group{display:flex;flex-direction:column;gap:6px}
.kv-glabel{font-size:11px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:#5A534D}
.kv-pills{display:flex;flex-wrap:wrap;gap:6px}
.kv-pill{min-height:36px;padding:0 12px;border-radius:8px;font-family:inherit;font-size:13px;font-weight:700;border:1px solid #C9D3C7;background:#fff;color:#24302A;cursor:pointer}
.kv-pill:hover{border-color:#33513A}
.kv-pill.sel{border-color:#33513A;background:#33513A;color:#fff}
.kv-dates{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.kv-date{min-height:36px;padding:0 10px;border:1px solid #C9D3C7;background:#fff;border-radius:8px;font-family:inherit;font-size:13px;color:#24302A}
.kv-dates span{font-size:13px;color:#5A534D}
.kv-toggle{min-height:40px;padding:0 14px;border-radius:999px;font-family:inherit;font-size:13px;font-weight:700;display:inline-flex;align-items:center;gap:8px;border:1px solid #C9D3C7;background:#fff;color:#24302A;cursor:pointer}
.kv-toggle .kv-tdot{width:12px;height:12px;border-radius:50%;border:2px solid #2F5D8A;background:#fff;display:inline-block}
.kv-toggle.on{border-color:#2F5D8A;background:#E4EDF7}
.kv-toggle.on .kv-tdot{background:#2F5D8A}
.kv-btn{margin-left:auto;min-height:40px;padding:0 16px;border:0;background:#33513A;color:#fff;border-radius:8px;font-family:inherit;font-size:13px;font-weight:700;display:inline-flex;align-items:center;gap:8px;cursor:pointer}
.kv-btn:hover{background:#26402D}
.kv-btn svg,.kv-pill svg{flex:0 0 auto}
.kv-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,460px),1fr));gap:16px}
.kv-chart{padding:16px 18px;display:flex;flex-direction:column;gap:10px;min-width:0}
.kv-chead{display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap}
.kv-ctitle{margin:0;font-size:15px;font-weight:800;color:#24302A}
.kv-csub{font-size:12px;color:#5A534D}
.kv-legend{display:flex;gap:6px 14px;flex-wrap:wrap;min-height:16px}
.kv-li{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:#3D3833}
.kv-sw{display:inline-block;width:14px;height:3px;border-radius:2px}
.kv-sw.bar{width:10px;height:10px}
.kv-sw.band{height:10px;opacity:.35}
.kv-sw.dash{height:0;border-top:2px dashed #6B635C;background:transparent!important}
.kv-body{display:flex;gap:8px}
.kv-yax{width:42px;height:190px;display:flex;flex-direction:column;justify-content:space-between;font-size:11px;color:#5A534D;text-align:right;flex:0 0 auto;font-variant-numeric:tabular-nums}
.kv-yax.r{text-align:left;width:46px}
.kv-plotwrap{flex:1 1 auto;min-width:0}
.kv-plot{position:relative;height:190px;cursor:crosshair}
.kv-svg{width:100%;height:190px;display:block;overflow:visible}
.kv-ln{fill:none;stroke-width:2;stroke-linejoin:round;stroke-linecap:round;vector-effect:non-scaling-stroke}
.kv-ln.cmp{stroke:#6B635C;stroke-dasharray:5 4;stroke-width:1.75}
.kv-gl{stroke:#E3E8E2;stroke-width:1;vector-effect:non-scaling-stroke}
.kv-band{opacity:.2}
.kv-xax{position:relative;height:16px;margin-top:6px;font-size:11px;color:#5A534D}
.kv-xax span{position:absolute;top:0;transform:translateX(-50%);white-space:nowrap}
.kv-guide{position:absolute;top:0;bottom:0;width:1px;background:#24302A;opacity:.35;display:none;pointer-events:none}
.kv-tip{position:absolute;top:6px;pointer-events:none;background:#24302A;color:#fff;font-size:12px;border-radius:8px;padding:8px 10px;white-space:nowrap;z-index:5;display:none;box-shadow:0 6px 18px rgba(0,0,0,.2);line-height:1.5}
.kv-tip b{display:block;font-weight:800;margin-bottom:2px}
.kv-tip i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;font-style:normal}
.kv-empty,.kv-loading{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:13px;color:#5A534D;background:rgba(255,255,255,.75);border-radius:6px}
.kv-spin{width:18px;height:18px;border:2px solid #C9D3C7;border-top-color:#33513A;border-radius:50%;animation:kvspin .8s linear infinite;margin-right:8px}
@keyframes kvspin{to{transform:rotate(360deg)}}
.kv-sum{overflow:hidden}
.kv-sum h2{margin:14px 18px;font-size:16px;font-weight:800;color:#24302A}
.kv-tblwrap{overflow-x:auto}
.kv-tbl{width:100%;border-collapse:collapse;font-size:13px}
.kv-tbl th{text-align:right;font-weight:700;color:#24302A;background:#EEF2EC;padding:9px 14px;border-bottom:1px solid #DCE3DA;white-space:nowrap}
.kv-tbl td{text-align:right;padding:9px 14px;border-bottom:1px solid #E7ECE5;color:#3D3833;font-variant-numeric:tabular-nums;white-space:nowrap}
.kv-tbl th:first-child,.kv-tbl td:first-child{text-align:left}
.kv-tbl td:first-child{font-weight:700;color:#24302A}
.kv-tbl tr:last-child td{border-bottom:0}
.kv-sync{padding:14px 18px;display:flex;flex-wrap:wrap;gap:8px 28px;font-size:13px;color:#3D3833;align-items:center}
.kv-sync strong{color:#24302A}
.kv-sync .bad{color:#B03A2E;font-weight:700}
.kv-msg{padding:28px;text-align:center;font-size:14px;color:#5A534D}
@media (max-width:640px){
  .kv-tab{padding:0 12px}
  .kv-live{display:none}
  .kv-btn{margin-left:0}
  .kv-kpi-v{font-size:22px}
}

descriptor.controllerScript:
// Kuvio · Pantalla de sensor — pestañas "Última semana" / "Histórico"
// Configuración: settings.perfil = lisimetro | agroclimatica | sonda4e | meteo | electrico
//                settings.inicioCampana = mes de inicio de campaña (1-12, por defecto 3)

var DAY = 86400000;
var MES = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
var DIA = ['dom','lun','mar','mié','jue','vie','sáb'];
var PAL = ['#2F5D8A','#5F8FC4','#8FA312','#C2601E','#6B635C'];
var FASES = ['#33513A','#5F8FC4','#C2601E'];

var PERFILES = {
  lisimetro: {
    eyebrow: 'Lisímetro',
    ficha: [{label: 'Finca', key: 'finca'}],
    kpis: [
      {key: 'cva_30', label: 'Humedad 30 cm', unit: '%', dec: 1},
      {key: 'deposito_nivel_mm', label: 'Nivel de depósito', unit: 'mm', dec: 0},
      {key: 'drenaje_lm2', label: 'Drenaje', unit: 'L/m²', dec: 1},
      {key: 'drenaje_ce_uscm', label: 'CE del drenaje', unit: 'µS/cm', dec: 0}
    ],
    charts: [
      {title: 'Humedad del suelo', unit: '%', dec: 1, band: true, series: [
        {key: 'cva_30', label: '30 cm', agg: 'AVG'}, {key: 'cva_60', label: '60 cm', agg: 'AVG'}, {key: 'cva_90', label: '90 cm', agg: 'AVG'}]},
      {title: 'Nivel de depósito', unit: 'mm', dec: 0, series: [{key: 'deposito_nivel_mm', label: 'Nivel', agg: 'MAX'}]},
      {title: 'Drenaje y CE', unit: 'L/m²', dec: 1, series: [
        {key: 'drenaje_lm2', label: 'Drenaje (L/m²)', agg: 'SUM', type: 'bar', color: '#5F8FC4'},
        {key: 'drenaje_ce_uscm', label: 'CE µS/cm (eje dcho.)', unit: 'µS/cm', dec: 0, agg: 'AVG', axis: 'r', color: '#C2601E'}]},
      {title: 'Temperatura del drenaje', unit: '°C', dec: 1, band: true, series: [{key: 'drenaje_temp', label: 'Temperatura', agg: 'AVG'}]}
    ],
    sync: [
      {label: 'Última sincronización', key: 'az_ultima_sincro', fmt: 'fecha'},
      {label: 'Valores OK', key: 'az_valores_ok'},
      {label: 'Fuera de rango', key: 'az_valores_fuera_rango', warnIfPositive: true}
    ]
  },
  agroclimatica: {
    eyebrow: 'Estación agroclimática',
    ficha: [{label: 'Zona', key: 'zona'}, {label: 'SIGPAC', key: 'sigpac'}, {label: 'Cultivo', key: 'cultivo'}, {label: 'Superficie', key: 'hectareas', unit: 'ha', dec: 1}],
    kpis: [
      {key: 'irrigation_1_1', label: 'Estado de riego', unit: '', dec: 0},
      {key: 'soil_ce_4', label: 'CE del suelo', unit: 'dS/m', dec: 2},
      {key: 'agroan_coldhours', label: 'Horas de frío', unit: 'h', dec: 0},
      {key: 'agroan_frozenhours', label: 'Horas de helada', unit: 'h', dec: 0},
      {key: 'agroan_hothours', label: 'Horas de calor', unit: 'h', dec: 0},
      {key: 'agroan_deltat', label: 'Delta T', unit: '°C', dec: 1}
    ],
    charts: [
      {title: 'Humedad del suelo', unit: '%', dec: 1, band: true, series: [
        {key: 'soil_hum_1', label: 'Superficial', agg: 'AVG'}, {key: 'soil_hum_2', label: 'Media', agg: 'AVG'}, {key: 'soil_hum_3', label: 'Profunda', agg: 'AVG'}]},
      {title: 'Temperatura del suelo', unit: '°C', dec: 1, band: true, series: [{key: 'soil_temp_5', label: 'Temperatura', agg: 'AVG', color: '#C2601E'}]},
      {title: 'Riego', unit: 'm³', dec: 1, series: [{key: 'irrigsumday', label: 'Riego del día', agg: 'DAYTOTAL', type: 'bar', color: '#33513A'}]}
    ],
    sync: []
  },
  sonda4e: {
    eyebrow: 'Sonda 4eGrowth',
    ficha: [{label: 'Finca', key: 'zona'}, {label: 'Parcela', key: 'sigpac'}, {label: 'Cultivo', key: 'cultivo'}, {label: 'Superficie', key: 'hectareas', unit: 'ha', dec: 1}],
    kpis: [
      {key: 'hum_suelo_media', label: 'Humedad media', unit: '%', dec: 1},
      {key: 'hum_suelo_30cm', label: 'Humedad 30 cm', unit: '%', dec: 1},
      {key: 'temp_suelo_30cm', label: 'Temp. suelo 30 cm', unit: '°C', dec: 1},
      {key: 'ce_suelo_30cm', label: 'CE 30 cm', unit: 'dS/m', dec: 2},
      {key: 'eto', label: 'ETo', unit: 'mm', dec: 2},
      {key: 'riego_acumulado_m3ha', label: 'Riego aplicado', unit: 'm³/ha', dec: 1}
    ],
    charts: [
      {title: 'Humedad del suelo por profundidad', unit: '%', dec: 1, band: true, series: [
        {key: 'hum_suelo_30cm', label: '30 cm', agg: 'AVG'}, {key: 'hum_suelo_60cm', label: '60 cm', agg: 'AVG'},
        {key: 'hum_suelo_90cm', label: '90 cm', agg: 'AVG'}, {key: 'hum_suelo_media', label: 'Media', agg: 'AVG', color: '#6B635C'}]},
      {title: 'Temperatura del suelo', unit: '°C', dec: 1, band: true, series: [
        {key: 'temp_suelo_30cm', label: '30 cm', agg: 'AVG', color: '#C2601E'}, {key: 'temp_suelo_60cm', label: '60 cm', agg: 'AVG', color: '#E0A070'},
        {key: 'temp_suelo_90cm', label: '90 cm', agg: 'AVG', color: '#8A5A3B'}]},
      {title: 'Conductividad eléctrica del suelo', unit: 'dS/m', dec: 2, band: true, series: [
        {key: 'ce_suelo_30cm', label: '30 cm', agg: 'AVG', color: '#6E8A12'}, {key: 'ce_suelo_60cm', label: '60 cm', agg: 'AVG', color: '#A9C316'},
        {key: 'ce_suelo_90cm', label: '90 cm', agg: 'AVG', color: '#33513A'}]},
      {title: 'ETo y precipitación', unit: 'mm', dec: 1, series: [
        {key: 'eto', label: 'ETo', agg: 'DAYTOTAL', type: 'bar', color: '#C9A227'},
        {key: 'precipitacion', label: 'Precipitación', agg: 'DAYTOTAL', type: 'bar', color: '#5F8FC4'}]},
      {title: 'Riego', unit: 'm³/ha', dec: 1, series: [
        {key: 'riego_acumulado_m3ha', label: 'Riego aplicado (m³/ha)', agg: 'DAYTOTAL', type: 'bar', color: '#33513A'},
        {key: 'riego_tiempo', label: 'Tiempo de riego (eje dcho.)', unit: '', agg: 'DAYTOTAL', axis: 'r', color: '#C2601E'}]}
    ],
    sync: [
      {label: 'Última sincronización', key: 'fg_ultima_sincro', fmt: 'fecha'},
      {label: 'Última lectura de la sonda', key: 'fg_ultima_lectura', fmt: 'fecha'},
      {label: 'Valores OK', key: 'fg_valores_ok'},
      {label: 'Fuera de rango', key: 'fg_valores_fuera_rango', warnIfPositive: true},
      {label: 'Último día saltado', key: 'fg_ultimo_error', fmt: 'fecha'}
    ]
  },
  meteo: {
    eyebrow: 'Estación meteorológica',
    ficha: [{label: 'Zona', key: 'zona'}, {label: 'SIGPAC', key: 'sigpac'}, {label: 'Cultivo', key: 'cultivo'}, {label: 'Superficie', key: 'hectareas', unit: 'ha', dec: 1}],
    kpis: [
      {key: 'agroan_coldhours', label: 'Horas de frío', unit: 'h', dec: 0},
      {key: 'agroan_frozenhours', label: 'Horas de helada', unit: 'h', dec: 0},
      {key: 'agroan_hothours', label: 'Horas de calor', unit: 'h', dec: 0},
      {key: 'agroan_deltat', label: 'Delta T', unit: '°C', dec: 1},
      {key: 'agroan_th', label: 'Integral térmica', unit: '°C·día', dec: 0}
    ],
    charts: [
      {title: 'Temperatura', unit: '°C', dec: 1, series: [
        {key: 'weather_tmed', label: 'Media', agg: 'AVG'}, {key: 'weather_tmax', label: 'Máxima', agg: 'MAX', color: '#C2601E'}]},
      {title: 'Humedad relativa', unit: '%', dec: 0, series: [
        {key: 'weather_hrmed', label: 'Media', agg: 'AVG'}, {key: 'weather_hrmax', label: 'Máxima', agg: 'MAX', color: '#5F8FC4'},
        {key: 'weather_hrmin', label: 'Mínima', agg: 'MIN', color: '#8FA312'}]},
      {title: 'Radiación solar', unit: 'W/m²', dec: 0, series: [
        {key: 'solar_radiation_1', label: 'Radiación (W/m²)', agg: 'AVG', color: '#C2601E'},
        {key: 'weather_accsr', label: 'Acumulada (eje dcho.)', unit: '', agg: 'MAX', axis: 'r', color: '#C9A227'}]},
      {title: 'Viento — velocidad', unit: 'm/s', dec: 1, series: [
        {key: 'wind_speed_2', label: 'Velocidad', agg: 'AVG'}, {key: 'weather_wsmed', label: 'Media', agg: 'AVG', color: '#5F8FC4'},
        {key: 'weather_wsmax', label: 'Máxima', agg: 'MAX', color: '#C2601E'}]},
      {title: 'Viento — dirección', unit: '°', dec: 0, series: [{key: 'wind_direction_3', label: 'Dirección', agg: 'AVG', color: '#5F8FC4'}]},
      {title: 'Lluvia y ETo', unit: 'mm', dec: 1, series: [
        {key: 'weather_sumrain', label: 'Lluvia', agg: 'DAYTOTAL', type: 'bar', color: '#5F8FC4'},
        {key: 'eto_pm', label: 'ETo', agg: 'DAYTOTAL', type: 'bar', color: '#C9A227'}]}
    ],
    sync: []
  },
  electrico: {
    eyebrow: 'Sensor eléctrico',
    titleFrom: 'label',
    ficha: [{label: 'Dispositivo', entity: 'name'}, {label: 'Batería', key: 'battery', src: 'ts', unit: 'V', dec: 2}, {label: 'Señal', key: 'signal', src: 'ts', dec: 0}],
    kpis: [
      {key: 'energia_importada_total_suma', label: 'Lectura', unit: 'kWh', dec: 0},
      {key: 'potencia_activa_total_raw', label: 'Potencia activa', unit: '', dec: 0},
      {key: 'factor_potencia_total', label: 'Factor de potencia', unit: '', dec: 3},
      {key: 'tension_L1_V', label: 'Tensión L1', unit: 'V', dec: 0},
      {key: 'tension_L2_V', label: 'Tensión L2', unit: 'V', dec: 0},
      {key: 'tension_L3_V', label: 'Tensión L3', unit: 'V', dec: 0}
    ],
    charts: [
      {title: 'Tensión por fase', unit: 'V', dec: 1, band: true, series: [
        {key: 'tension_L1_V', label: 'L1', agg: 'AVG', color: FASES[0]}, {key: 'tension_L2_V', label: 'L2', agg: 'AVG', color: FASES[1]}, {key: 'tension_L3_V', label: 'L3', agg: 'AVG', color: FASES[2]}]},
      {title: 'Corriente por fase', unit: '', dec: 1, band: true, series: [
        {key: 'corriente_L1_raw', label: 'L1', agg: 'AVG', color: FASES[0]}, {key: 'corriente_L2_raw', label: 'L2', agg: 'AVG', color: FASES[1]}, {key: 'corriente_L3_raw', label: 'L3', agg: 'AVG', color: FASES[2]}]},
      {title: 'Potencias', unit: '', dec: 1, series: [
        {key: 'potencia_activa_total_raw', label: 'Activa', agg: 'AVG', color: FASES[0]}, {key: 'potencia_reactiva_total_raw', label: 'Reactiva', agg: 'AVG', color: FASES[1]},
        {key: 'potencia_aparente_total_raw', label: 'Aparente', agg: 'AVG', color: FASES[2]}]},
      {title: 'Factor de potencia', unit: '', dec: 3, band: true, series: [{key: 'factor_potencia_total', label: 'FP total', agg: 'AVG', color: FASES[0]}]},
      {title: 'Energía consumida por fase', unit: '', dec: 1, series: [
        {key: 'energia_importada_L1_raw', label: 'L1', agg: 'DIFF', type: 'bar', color: FASES[0]},
        {key: 'energia_importada_L2_raw', label: 'L2', agg: 'DIFF', type: 'bar', color: FASES[1]},
        {key: 'energia_importada_L3_raw', label: 'L3', agg: 'DIFF', type: 'bar', color: FASES[2]}]},
      {title: 'Consumo total acumulado', unit: 'kWh', dec: 0, series: [{key: 'energia_importada_total_suma', label: 'Contador', agg: 'COUNTER', color: FASES[0]}]},
      {title: 'Batería y señal', unit: 'V', dec: 2, series: [
        {key: 'battery', label: 'Batería (V)', agg: 'AVG', color: FASES[0]}, {key: 'signal', label: 'Señal (eje dcho.)', unit: '', dec: 0, agg: 'AVG', axis: 'r', color: FASES[1]}]}
    ],
    sync: []
  }
};

// Agregaciones diarias que hay que pedir a ThingsBoard según el tipo de variable
var NEED = {AVG: ['AVG','MIN','MAX'], SUM: ['SUM'], MAX: ['MAX'], MIN: ['MIN'], DAYTOTAL: ['MAX'], COUNTER: ['MAX','MIN'], DIFF: ['MAX','MIN']};
var AGG_TXT = {AVG: 'media', SUM: 'suma', MAX: 'máximo', MIN: 'mínimo', DAYTOTAL: 'total', COUNTER: 'lectura', DIFF: 'consumo'};
var BUCKET_TXT = {day: 'diaria', week: 'semanal', month: 'mensual'};

var ICON_DL = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 4v11M7 10l5 5 5-5M5 20h14"/></svg>';

// ---------- utilidades ----------
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function fnum(n, d) {
