      var aggs = [['auto', 'Auto'], ['day', 'Día'], ['week', 'Semana'], ['month', 'Mes']];
      h += '<div class="kv-toolbar">' +
        '<div class="kv-group"><span class="kv-glabel">Rango</span><div class="kv-pills">' + presets.map(function (p) {
          var sel = S.preset === p[0], lab = p[0] === 'camp' && R && S.preset === 'camp' ? R.label : p[1];
          return '<button type="button" class="kv-pill' + (sel ? ' sel' : '') + '" aria-pressed="' + sel + '" data-act="preset" data-v="' + p[0] + '">' + esc(lab) + '</button>';
        }).join('') + '</div></div>' +
        '<div class="kv-group"><span class="kv-glabel">Fechas</span><div class="kv-dates">' +
          '<input class="kv-date" type="date" aria-label="Desde" data-act="from" value="' + isoDate(R.start) + '" max="' + isoDate(now) + '">' +
          '<span>a</span><input class="kv-date" type="date" aria-label="Hasta" data-act="to" value="' + isoDate(R.end - DAY) + '" max="' + isoDate(now) + '"></div></div>' +
        '<div class="kv-group"><span class="kv-glabel">Agregación</span><div class="kv-pills">' + aggs.map(function (a) {
          var sel = S.agg === a[0], lab = a[0] === 'auto' && sel ? 'Auto (' + ({day: 'día', week: 'semana', month: 'mes'})[R.mode] + ')' : a[1];
          return '<button type="button" class="kv-pill' + (sel ? ' sel' : '') + '" aria-pressed="' + sel + '" data-act="agg" data-v="' + a[0] + '">' + lab + '</button>';
        }).join('') + '</div></div>' +
        '<button type="button" class="kv-toggle' + (S.cmp ? ' on' : '') + '" aria-pressed="' + S.cmp + '" data-act="cmp"><span class="kv-tdot"></span>Comparar con año anterior</button>' +
        '<button type="button" class="kv-btn" data-act="csv">' + ICON_DL + 'Descargar CSV</button>' +
        '</div>';
    }
    return h + '</div>';
  }

  function renderChart(v, idx) {
    var c = v.chart;
    var legend = (v.series || c.series.map(function (s, i) { return {s: s, color: s.color || PAL[i % PAL.length]}; })).map(function (x) {
      return '<span class="kv-li"><span class="kv-sw' + (x.s.type === 'bar' ? ' bar' : '') + '" style="background:' + x.color + '"></span>' + esc(x.s.label) + '</span>';
    });
    if (v.series && v.series[0] && v.series[0].band) legend.push('<span class="kv-li"><span class="kv-sw band" style="background:' + v.series[0].color + '"></span>Rango ' + esc(v.series[0].s.label) + '</span>');
    if (v.cmp) legend.push('<span class="kv-li"><span class="kv-sw dash"></span>Año anterior</span>');
    var head = '<article class="kv-card kv-chart"><div class="kv-chead"><h3 class="kv-ctitle">' + esc(c.title) + (c.unit ? ' (' + esc(c.unit) + ')' : '') + '</h3><span class="kv-csub">' + esc(v.sub || '') + '</span></div>' +
      '<div class="kv-legend">' + legend.join('') + '</div>';
    if (!v.series) {
      return head + '<div class="kv-body"><div class="kv-yax"></div><div class="kv-plotwrap"><div class="kv-plot">' +
        (v.error ? '<div class="kv-empty">No se han podido cargar los datos</div>' : '<div class="kv-loading"><span class="kv-spin"></span>Cargando…</div>') +
        '</div><div class="kv-xax"></div></div></div></article>';
    }
    // dominios
    var L = [], Rr = [], anyBarL = false, anyBarR = false, hasR = false;
    v.series.forEach(function (x) {
      var tgt = x.s.axis === 'r' ? Rr : L;
      if (x.s.axis === 'r') { hasR = true; if (x.s.type === 'bar') anyBarR = true; } else if (x.s.type === 'bar') anyBarL = true;
      x.pts.forEach(function (p) { tgt.push(p.v); if (x.band) { if (p.lo != null) tgt.push(p.lo); if (p.hi != null) tgt.push(p.hi); } });
    });
    if (v.cmp) v.cmp.forEach(function (p) { L.push(p.v); });
    var mm = function (a) { return a.length ? [Math.min.apply(null, a), Math.max.apply(null, a)] : [null, null]; };
    var lr = mm(L), rr = mm(Rr);
    var dl = niceDomain(lr[0], lr[1], anyBarL), dr = niceDomain(rr[0], rr[1], anyBarR);
    var W = 600, Hh = 170, t0 = v.t0, t1 = v.t1;
    var X = function (t) { return ((t - t0) / (t1 - t0) * W); };
    var Y = function (val, d) { return Hh - (Math.max(d[0], Math.min(d[1], val)) - d[0]) / (d[1] - d[0]) * Hh; };
    var svg = ['<line x1="0" y1="0.5" x2="600" y2="0.5" class="kv-gl"/><line x1="0" y1="85" x2="600" y2="85" class="kv-gl"/><line x1="0" y1="169.5" x2="600" y2="169.5" class="kv-gl"/>'];
    var nBars = v.series.filter(function (x) { return x.s.type === 'bar'; }).length, bi = 0, empty = true;
    // bandas
    v.series.forEach(function (x) {
      if (!x.band) return;
      var d = x.s.axis === 'r' ? dr : dl, seg = [];
      var flush = function () {
        if (seg.length > 1) svg.push('<polygon class="kv-band" fill="' + x.color + '" points="' + seg.map(function (p) { return X(p.t).toFixed(1) + ',' + Y(p.hi, d).toFixed(1); }).concat(seg.slice().reverse().map(function (p) { return X(p.t).toFixed(1) + ',' + Y(p.lo, d).toFixed(1); })).join(' ') + '"/>');
        seg = [];
      };
      x.pts.forEach(function (p, i) {
        var prevP = x.pts[i - 1];
        if (prevP && p.t0 && prevP.t1 && p.t0 - prevP.t1 > DAY / 2) flush();
        if (p.lo != null && p.hi != null) seg.push(p); else flush();
      });
      flush();
    });
    // barras
    v.series.forEach(function (x) {
      if (x.s.type !== 'bar') return;
      var d = x.s.axis === 'r' ? dr : dl, path = '', base = Y(Math.max(d[0], 0), d);
      x.pts.forEach(function (p) {
        empty = false;
        var a = X(p.t0), b = X(p.t1), wAll = (b - a) * 0.72, w = Math.max(0.6, wAll / nBars), xx = a + (b - a) * 0.14 + bi * w, y = Y(p.v, d);
        path += 'M' + xx.toFixed(1) + ' ' + Math.min(y, base).toFixed(1) + 'h' + w.toFixed(1) + 'V' + Math.max(y, base).toFixed(1) + 'h' + (-w).toFixed(1) + 'Z';
      });
      svg.push('<path fill="' + x.color + '" d="' + path + '"/>');
      bi++;
    });
    // líneas (de la última a la primera para que la primera quede encima)
    var linePath = function (pts, d, raw) {
      var out = '', last = null, gap;
      if (raw) {
        var dts = []; for (var i = 1; i < pts.length; i++) dts.push(pts[i].t - pts[i - 1].t);
        dts.sort(function (a, b) { return a - b; });
        gap = Math.max(3 * (dts[Math.floor(dts.length / 2)] || 0), 3 * 3600000);
      } else gap = null;
      pts.forEach(function (p) {
        var brk = !last || (raw ? p.t - last.t > gap : (p.t0 - last.t1 > DAY / 2));
        out += (brk ? 'M' : 'L') + X(p.t).toFixed(1) + ' ' + Y(p.v, d).toFixed(1);
        last = p;
      });
      return out;
    };
    v.series.slice().reverse().forEach(function (x) {
      if (x.s.type === 'bar' || !x.pts.length) return;
      empty = false;
      var d = x.s.axis === 'r' ? dr : dl, pts = x.pts;
      if (pts.length === 1) { svg.push('<circle cx="' + X(pts[0].t).toFixed(1) + '" cy="' + Y(pts[0].v, d).toFixed(1) + '" r="3" fill="' + x.color + '"/>'); return; }
      svg.push('<path class="kv-ln" stroke="' + x.color + '" d="' + linePath(pts, d, v.raw) + '"/>');
    });
    if (v.cmp && v.cmp.length > 1) svg.push('<path class="kv-ln cmp" d="' + linePath(v.cmp, dl, false) + '"/>');
    var dec = decFor(dl[0], dl[1]), decr = decFor(dr[0], dr[1]);
    var yl = '<div class="kv-yax"><span>' + fnum(dl[1], dec) + '</span><span>' + fnum((dl[0] + dl[1]) / 2, dec) + '</span><span>' + fnum(dl[0], dec) + '</span></div>';
    var yr = hasR ? '<div class="kv-yax r"><span>' + fnum(dr[1], decr) + '</span><span>' + fnum((dr[0] + dr[1]) / 2, decr) + '</span><span>' + fnum(dr[0], decr) + '</span></div>' : '';
    var xl = v.xl.map(function (l, i) {
      var pct = (l.t - t0) / (t1 - t0) * 100, al = '';
      return '<span style="left:' + pct.toFixed(2) + '%">' + esc(l.txt) + '</span>';
    }).join('');
    var overlay = loading ? '<div class="kv-loading"><span class="kv-spin"></span>Cargando…</div>' : (empty ? '<div class="kv-empty">Sin datos en este periodo</div>' : '');
    return head + '<div class="kv-body">' + yl + '<div class="kv-plotwrap"><div class="kv-plot" data-chart="' + idx + '">' +
      '<svg class="kv-svg" viewBox="0 0 600 170" preserveAspectRatio="none" role="img" aria-label="' + esc(c.title) + '">' + svg.join('') + '</svg>' +
      '<div class="kv-guide"></div><div class="kv-tip"></div>' + overlay + '</div><div class="kv-xax">' + xl + '</div></div>' + yr + '</div></article>';
  }

  function renderSummary() {
    if (loading && !summary.length) return '';
    var R = rango;
    var rows = summary.map(function (r) {
      return '<tr><td>' + esc(r.label) + '</td><td>' + (r.counter ? '—' : r.avg) + '</td><td>' + r.min + '</td><td>' + r.max + '</td><td>' + r.tot + '</td></tr>';
    }).join('');
    return '<section class="kv-card kv-sum"><h2>Resumen del periodo · ' + (R ? esc(dlong(R.start) + ' – ' + dlong(R.end - DAY)) : '') + '</h2><div class="kv-tblwrap"><table class="kv-tbl">' +
      '<thead><tr><th>Variable</th><th>Media diaria</th><th>Mínimo</th><th>Máximo</th><th>Total / consumo</th></tr></thead><tbody>' + rows + '</tbody></table></div></section>';
  }

  function renderSync() {
    if (!P.sync.length) return '';
    var items = P.sync.map(function (it) {
      var v = head.attrs[it.key], bad = it.warnIfPositive && toNum(v) > 0;
      return '<span>' + esc(it.label) + ': <b class="' + (bad ? 'bad' : '') + '">' + esc(fmtValor(v, it)) + '</b></span>';
    }).join('');
    return '<section class="kv-card kv-sync"><strong>Estado de sincronización</strong>' + items + '</section>';
  }

  // ---------- tooltip ----------
  function nearest(pts, t) {
    var lo = 0, hi = pts.length - 1;
    if (hi < 0) return null;
    while (hi - lo > 1) { var m = (lo + hi) >> 1; if (pts[m].t < t) lo = m; else hi = m; }
    return Math.abs(pts[lo].t - t) <= Math.abs(pts[hi].t - t) ? pts[lo] : pts[hi];
  }
  function tipDate(t, v) {
    if (v.raw) { var d = new Date(t); return DIA[d.getDay()] + ' ' + dshort(t) + ', ' + hhmm(t); }
    if (v.mode === 'week') return 'Semana del ' + dshort(t);
    if (v.mode === 'month') { var m = new Date(t); return MES[m.getMonth()] + ' ' + m.getFullYear(); }
    return dlong(t);
  }
  function onMove(e) {
    var plot = e.target.closest && e.target.closest('.kv-plot[data-chart]');
    root.querySelectorAll('.kv-plot').forEach(function (p) { if (p !== plot) { var g = p.querySelector('.kv-guide'), tp = p.querySelector('.kv-tip'); if (g) g.style.display = 'none'; if (tp) tp.style.display = 'none'; } });
    if (!plot || loading) return;
    var v = views[+plot.getAttribute('data-chart')];
    if (!v || !v.series) return;
    var rect = plot.getBoundingClientRect(), fx = (e.clientX - rect.left) / rect.width;
    if (fx < 0 || fx > 1) return;
    var t = v.t0 + fx * (v.t1 - v.t0), anchor = null, rows = [];
    v.series.forEach(function (x) {
      var p = nearest(x.pts, t);
      if (!p) return;
      if (!anchor || Math.abs(p.t - t) < Math.abs(anchor.t - t)) anchor = p;
    });
    if (!anchor) return;
    var tol = v.raw ? 3 * 3600000 : (anchor.t1 - anchor.t0 || DAY) * 0.6;
    v.series.forEach(function (x) {
      var p = nearest(x.pts, anchor.t), unit = x.s.unit != null ? x.s.unit : v.chart.unit, dec = x.s.dec != null ? x.s.dec : v.chart.dec;
      if (!p || Math.abs(p.t - anchor.t) > tol) return;
      var extra = x.band && p.lo != null ? ' <span style="opacity:.75">(' + fnum(p.lo, dec) + '–' + fnum(p.hi, dec) + ')</span>' : '';
      rows.push('<div><i style="background:' + x.color + '"></i>' + esc(x.s.label.replace(/\s*\(.*\)\s*$/, '')) + ': <b style="display:inline">' + fnum(p.v, dec) + (unit ? ' ' + esc(unit) : '') + '</b>' + extra + '</div>');
    });
    if (v.cmp) {
      var q = nearest(v.cmp, anchor.t);
      if (q && Math.abs(q.t - anchor.t) <= tol) rows.push('<div><i style="background:#6B635C"></i>Año anterior: <b style="display:inline">' + fnum(q.v, v.chart.dec) + '</b></div>');
    }
    var g = plot.querySelector('.kv-guide'), tp = plot.querySelector('.kv-tip'), px = (anchor.t - v.t0) / (v.t1 - v.t0) * rect.width;
    g.style.display = 'block'; g.style.left = px + 'px';
    tp.innerHTML = '<b>' + esc(tipDate(anchor.t, v)) + '</b>' + rows.join('');
    tp.style.display = 'block';
    var tw = tp.offsetWidth;
    tp.style.left = (px + 12 + tw > rect.width ? Math.max(0, px - 12 - tw) : px + 12) + 'px';
  }
  function onLeave() {
    root.querySelectorAll('.kv-guide,.kv-tip').forEach(function (el) { el.style.display = 'none'; });
  }

  // ---------- CSV ----------
  function csv() {
    var R = rango, lines = [], sep = ';';
    var fmt = function (n) { return n == null ? '' : String(Math.round(n * 1000) / 1000).replace('.', ','); };
    lines.push(['Sensor', (ent && (ent.label || ent.name)) || ''].join(sep));
    lines.push(['Periodo', R ? dlong(R.start) + ' - ' + dlong(R.end - DAY) : ''].join(sep));
    lines.push(['Agregación', R ? BUCKET_TXT[R.mode] : ''].join(sep));
    lines.push('');
    var cols = [], map = {};
    views.forEach(function (v) {
      (v.series || []).forEach(function (x) {
        var unit = x.s.unit != null ? x.s.unit : v.chart.unit, name = v.chart.title + ' · ' + x.s.label.replace(/\s*\(.*\)\s*$/, '') + ' [' + AGG_TXT[x.s.agg] + ']' + (unit ? ' (' + unit + ')' : '');
        if (cols.some(function (cc) { return cc.key === x.s.key + x.s.agg; })) return;
        var col = {key: x.s.key + x.s.agg, name: name, band: x.band};
        cols.push(col);
        x.pts.forEach(function (p) {
          var k = p.t0 != null ? p.t0 : p.t;
          map[k] = map[k] || {};
          map[k][col.key] = p;
        });
      });
    });
    var header = ['Fecha'];
    cols.forEach(function (c) { header.push(c.name); if (c.band) { header.push(c.name + ' mín'); header.push(c.name + ' máx'); } });
    lines.push(header.map(function (h) { return '"' + h.replace(/"/g, '""') + '"'; }).join(sep));
    Object.keys(map).map(Number).sort(function (a, b) { return a - b; }).forEach(function (t) {
      var row = [isoDate(t)];
      cols.forEach(function (c) { var p = map[t][c.key]; row.push(p ? fmt(p.v) : ''); if (c.band) { row.push(p ? fmt(p.lo) : ''); row.push(p ? fmt(p.hi) : ''); } });
      lines.push(row.join(sep));
    });
    var blob = new Blob(['﻿' + lines.join('\r\n')], {type: 'text/csv;charset=utf-8'});
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = ((ent && (ent.label || ent.name)) || 'sensor').replace(/[^\w\-]+/g, '_') + '_historico_' + (R ? isoDate(R.start) + '_' + isoDate(R.end - DAY) : '') + '.csv';
    document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500);
  }

  // ---------- eventos ----------
  root.addEventListener('click', function (e) {
    var b = e.target.closest && e.target.closest('[data-act]');
    if (!b || b.tagName === 'INPUT') return;
    var act = b.getAttribute('data-act'), val = b.getAttribute('data-v');
    if (act === 'tab') { if (S.tab === val) return; S.tab = val; views = []; load(); }
    else if (act === 'preset') {
      if (val === 'custom' && S.preset !== 'custom') { var R0 = rango || calcRango(); S.from = isoDate(R0.start); S.to = isoDate(R0.end - DAY); }
      S.preset = val; load();
    }
    else if (act === 'agg') { S.agg = val; load(); }
    else if (act === 'cmp') { S.cmp = !S.cmp; load(); }
    else if (act === 'csv') csv();
  });
  root.addEventListener('change', function (e) {
    var act = e.target.getAttribute && e.target.getAttribute('data-act');
    if (act !== 'from' && act !== 'to') return;
    var R0 = rango || calcRango();
    if (S.preset !== 'custom') { S.from = isoDate(R0.start); S.to = isoDate(R0.end - DAY); S.preset = 'custom'; }
    if (act === 'from') S.from = e.target.value; else S.to = e.target.value;
    load();
  });
  root.addEventListener('mousemove', onMove);
  root.addEventListener('mouseleave', onLeave);

  function start() {
    var e = currentEntity();
    if (!e) { ent = null; render(); return; }
    if (ent && ent.id === e.id) return;
    ent = e; head = {attrs: {}, latest: {}, prev: {}, created: null}; views = []; summary = []; rango = null;
    render();
    loadHead().then(render);
    load();
  }
  self._kv.start = start;
  self._kv.refresh = function () {
    if (!ent) return;
    loadHead().then(render);
    if (S.tab === 'semana') load();
  };
  clearInterval(self._kv.timer);
  self._kv.timer = setInterval(function () { self._kv.refresh(); }, 5 * 60 * 1000);
  start();
};

function ensureFonts() {
  if (document.getElementById('kv-fonts')) return;
  var l = document.createElement('link');
  l.id = 'kv-fonts'; l.rel = 'stylesheet';
  l.href = 'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Mulish:wght@400;600;700;800&display=swap';
  document.head.appendChild(l);
}

self.onDataUpdated = function () { if (self._kv && self._kv.start) self._kv.start(); };
self.onResize = function () {};
self.onDestroy = function () { if (self._kv) clearInterval(self._kv.timer); };

self.typeParameters = function () {
  return {maxDatasources: 1, maxDataKeys: 1, dataKeysOptional: true, singleEntity: true};
};
